import { conversations, opportunities } from "./data.js";
import { icon, badge, button, pageHeader, metric, panel } from "./core.js";

export function inboxPage() {
  const selected=conversations[0];
  return `<div class="conversation-layout">
    <aside class="conversation-list">
      <div class="sticky top-0 z-10 border-b border-line bg-white p-4"><div class="flex items-center justify-between"><h1 class="text-lg font-semibold">Inbox</h1>${button("Filtres","SlidersHorizontal")}</div><div class="relative mt-3">${icon("Search",15,"absolute left-3 top-2.5 text-muted")}<input class="input pl-9" placeholder="Rechercher une conversation"></div><div class="mt-3 tabs"><button class="tab active">À traiter 3</button><button class="tab">Toutes</button></div></div>
      ${conversations.map((c,i)=>`<button class="w-full border-b border-line p-4 text-left hover:bg-canvas ${i===0?"bg-[#f4fbe7]":""}"><div class="flex gap-3"><span class="avatar ${i===0?"avatar-signal":""}">${c.initials}</span><span class="min-w-0 flex-1"><span class="flex items-center justify-between gap-2"><strong class="truncate">${c.name}</strong><time class="text-[10px] text-muted">${c.time}</time></span><span class="mt-0.5 block truncate text-xs text-muted">${c.company}</span><span class="mt-2 block line-clamp-2 text-xs leading-5">${c.preview}</span><span class="mt-2 flex items-center justify-between">${badge(c.status,i===0?"warning":i===2?"success":"")} ${c.unread?`<span class="grid h-5 w-5 place-items-center rounded-full bg-navy text-[10px] text-white">${c.unread}</span>`:""}</span></span></div></button>`).join("")}
    </aside>
    <section class="conversation-main">
      <header class="flex h-16 items-center justify-between border-b border-line bg-white px-5"><div class="identity"><span class="avatar avatar-signal">${selected.initials}</span><span><span class="identity-name">${selected.name}</span><span class="identity-meta">${selected.company} · LinkedIn</span></span></div><div class="flex gap-2">${button("Qualifier","Tags")}${button("Créer une opportunité","BadgeEuro","primary")}</div></header>
      <div class="flex flex-1 flex-col overflow-y-auto p-5 md:p-8">
        <div class="mx-auto flex w-full max-w-3xl flex-1 flex-col">
          <div class="my-3 self-center text-[10px] font-semibold uppercase tracking-wide text-muted">Hier</div>
          <div class="bubble bubble-out" data-pretext>Bonjour Sophie, j’ai vu que Mutuelle Nova lançait un chantier de gouvernance des usages IA. Nous accompagnons des équipes data qui doivent industrialiser leurs assistants tout en gardant la traçabilité des sources et des accès. Est-ce déjà un sujet prioritaire chez vous ?</div>
          <div class="mt-1 self-end text-[10px] text-muted">Hier, 16:08 · Envoyé</div>
          <div class="bubble bubble-in mt-5" data-pretext>Bonjour Salim. Oui, le sujet gouvernance nous concerne. Nous avons déjà quelques POC mais rien de vraiment industrialisé.</div>
          <div class="bubble bubble-in" data-pretext>Vous avez déjà travaillé avec des environnements où les données sont très sensibles ?</div>
          <div class="mt-1 text-[10px] text-muted">Aujourd’hui, 09:42</div>
          <div class="mt-6 rounded-lg border border-[#d7f69b] bg-[#f6ffe5] p-4"><div class="flex items-center justify-between"><div class="flex items-center gap-2 font-semibold text-signal-ink">${icon("Sparkles",16)}Brouillon IA</div>${badge("Validation obligatoire","warning")}</div><div class="mt-3 rounded-lg border border-[#d7f69b] bg-white p-3 leading-6" contenteditable="true" data-pretext>Oui. Nous déployons notamment IgnitionRAG dans des environnements privés avec contrôle d’accès par collection, traçabilité des sources et validation des réponses. Le plus utile serait de comprendre vos contraintes de sécurité avant de parler architecture. Vous seriez disponible 30 minutes mardi ou mercredi ?</div><div class="mt-3 flex flex-wrap justify-between gap-2"><button class="text-xs font-semibold text-brandblue" data-toast="Sources du brouillon affichées">3 sources utilisées</button><div class="flex gap-2">${button("Rejeter","X")}${button("Approuver et envoyer","Send","signal")}</div></div></div>
        </div>
      </div>
      <footer class="border-t border-line bg-white p-4"><div class="mx-auto flex max-w-3xl items-end gap-2"><button class="btn icon-btn">${icon("Paperclip")}</button><textarea class="textarea min-h-[44px] flex-1" placeholder="Écrire une réponse…"></textarea><button class="btn btn-primary h-11">${icon("Send")}Envoyer</button></div></footer>
    </section>
    <aside class="conversation-context p-5"><div class="flex items-center gap-3"><span class="avatar avatar-lg avatar-signal">SB</span><div><div class="font-semibold">Sophie Bernard</div><div class="text-xs text-muted">Directrice Data & IA</div></div></div><div class="mt-5 space-y-3 text-xs">${[["Entreprise","Mutuelle Nova"],["Score ICP","88 / 100"],["Intention","Intéressée"],["Campagne","CTO · RAG Entreprise"],["Étape","Conversation"],["Owner","Salim"]].map(([k,v])=>`<div class="flex justify-between gap-3 border-b border-line pb-2"><span class="text-muted">${k}</span><strong class="text-right">${v}</strong></div>`).join("")}</div><div class="mt-5 rounded-lg border border-line p-3"><div class="text-xs font-semibold">Prochaine action</div><p class="mt-1 text-xs leading-5 text-muted">Répondre sur la sécurité, puis proposer un atelier de cadrage.</p></div><button class="btn mt-4 w-full">${icon("UserRound")}Ouvrir le prospect</button></aside>
  </div>`;
}

export function pipelinePage() {
  const stages=["Conversation","Qualifié","Rendez-vous","Opportunité","Proposition"];
  return `
    ${pageHeader("Pipeline", "Suivez la valeur commerciale créée par la prospection, jusqu’au revenu.", button("Nouvelle opportunité","Plus","primary"))}
    <section class="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric("Pipeline brut","199 k€","+24 k€")}${metric("Pipeline pondéré","61,4 k€","+9,2 k€")}${metric("Cycle moyen","18 jours","-3 j")}${metric("Gagné ce trimestre","72 k€","2 deals")}</section>
    <div class="mb-5 flex flex-wrap items-center justify-between gap-3"><div class="tabs"><button class="tab active">Kanban</button><button class="tab">Liste</button><button class="tab">Prévision</button></div><div class="flex gap-2">${button("Tous les owners","Users")}${button("Toutes les offres","Package")}</div></div>
    <section class="kanban">${stages.map(stage=>{const cards=opportunities.filter(o=>o.stage===stage);return `<div class="kanban-column"><div class="flex items-center justify-between px-1"><div><span class="font-semibold">${stage}</span><span class="ml-2 text-xs text-muted">${cards.length}</span></div><span class="font-mono text-xs">${cards.reduce((sum,c)=>sum+parseInt(c.value.replaceAll(" ","")),0).toLocaleString("fr-FR")} €</span></div>${cards.length?cards.map(o=>`<article class="kanban-card"><div class="flex items-start justify-between gap-2"><div class="font-semibold">${o.company}</div>${badge(o.age)}</div><p class="mt-1 text-xs text-muted">${o.title}</p><div class="mt-4 font-mono text-lg font-semibold">${o.value}</div><div class="mt-3 progress"><span style="width:${o.probability}%"></span></div><div class="mt-3 flex items-center justify-between text-[11px] text-muted"><span>${o.contact}</span><span>${o.probability} %</span></div><div class="mt-3 border-t border-line pt-3 text-xs">${icon("Calendar",13,"mr-1 inline")} ${o.next}</div></article>`).join(""):`<div class="empty py-10 text-xs">Aucune opportunité</div>`}</div>`}).join("")}
      <div class="kanban-column"><div class="flex items-center justify-between px-1"><div><span class="font-semibold">Gagné</span><span class="ml-2 text-xs text-muted">2</span></div><span class="font-mono text-xs">72 000 €</span></div><article class="kanban-card border-success/30"><div class="flex items-start justify-between"><div class="font-semibold">Arcadia Énergie</div>${badge("Gagné","success")}</div><p class="mt-1 text-xs text-muted">Audit et pilote RAG</p><div class="mt-4 font-mono text-lg font-semibold">42 000 €</div><div class="mt-3 text-xs text-muted">Clos le 21 juillet · 24 jours</div></article></div>
    </section>`;
}
